CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20261028065512_Initial_OptiFlow_PostgreSql_Schema') THEN
    CREATE TABLE allocations (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "RunDate" timestamp with time zone NOT NULL,
        "RunBy" character varying(100) NOT NULL,
        "SummaryJson" text,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
        "UpdatedAtUtc" timestamp with time zone,
        "ConcurrencyToken" bytea,
        CONSTRAINT "PK_allocations" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
