    CREATE TABLE allocation_lines (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "AllocationId" integer NOT NULL,
        "GapId" integer NOT NULL,
        "StoreName" character varying(150) NOT NULL,
        "StoreCategory" character varying(20) NOT NULL,
        "StoreType" character varying(30) NOT NULL,
        "Region" text,
        "Zone" text,
        "BrandCode" character varying(20) NOT NULL,
        "BrandName" character varying(100) NOT NULL,
        "Commodity" character varying(30) NOT NULL,
        "Facing" double precision NOT NULL,
        "BackStock" double precision NOT NULL,
        "CurrentSoh" double precision NOT NULL,
        "Deficit" double precision NOT NULL,
        "InitialGap" double precision NOT NULL,
        "RemainingGap" double precision NOT NULL,
        "RequestedItemCode" text,
        "AllocatedItemCode" character varying(50),
        "AllocatedItemName" character varying(250),
        "AllocatedBarcode" character varying(50),
        "AllocatedQty" integer NOT NULL,
        "MatchType" character varying(30) NOT NULL,
        "Mrp" numeric(18,2) NOT NULL,
        "MatchReason" character varying(250) NOT NULL,
        "ColorLimitWarning" boolean NOT NULL,
        "SimilarityScore" double precision,
        "RequestedAttributesJson" text,
        "AllocatedAttributesJson" text,
        "CreatedAtUtc" timestamp with time zone NOT NULL,
