        "ConcurrencyToken" bytea,
        CONSTRAINT "PK_allocation_lines" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_allocation_lines_allocations_AllocationId" FOREIGN KEY ("AllocationId") REFERENCES allocations ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

